<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= htmlspecialchars($title, ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="/assets/app.css"></head><body>
<nav class="topbar"><a class="brand" href="/">FPDP</a><span class="nav-links"><a href="/dashboard">Dashboard</a><a href="/dashboard/posts" class="owner-nav hidden">Post editor</a><a href="/dashboard/posts/list" class="owner-nav hidden">My posts</a><a href="/dashboard/cv" class="owner-nav hidden">CV &amp; Resume</a><a href="/dashboard/integrations" class="owner-nav hidden">Integrations</a><a href="/timeline">Timeline</a></span></nav>
<main class="shell dashboard-shell"><section class="panel"><p class="eyebrow">Owner dashboard</p><h1>CV &amp; Resume</h1><p id="auth-summary" class="muted">Masuk untuk mengelola CV.</p><form id="login-form" class="stack"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button>Masuk</button></form><button id="logout-button" class="secondary hidden">Keluar</button></section>
<section id="cv-content" class="hidden two-col cv-columns"><section class="panel"><h2>Upload atau ganti CV</h2><p class="muted">PDF, DOC, atau DOCX; maksimum 5 MB. Mengganti file mencabut akses versi sebelumnya.</p><form id="cv-form" class="stack"><label>Judul<input name="title" maxlength="128" required placeholder="CV Nama Anda"></label><label>File CV<input name="file" type="file" accept=".pdf,.doc,.docx,application/pdf,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required></label><div class="field-row"><label>Harga<input name="price_amount" type="number" min="0" step="0.01" value="0" required></label><label>Mata uang<select name="price_currency"><option value="IDR">IDR</option><option value="USD">USD</option></select></label></div><p class="muted">Harga 0 berarti gratis. Untuk PayPal pilih USD.</p><button id="upload-button">Simpan CV</button></form></section>
<section class="panel"><h2>CV aktif</h2><div id="current-cv"><p class="muted">Belum ada CV.</p></div><a id="public-cv-link" class="button secondary hidden" target="_blank" rel="noopener">Buka halaman publik</a></section></section><p id="cv-status" class="status" role="status" aria-live="polite"></p></main><script src="/assets/dashboard-cv.js" defer></script></body></html>
